import{_ as l,a0 as o,w as r,s as d,ao as t,I as p,x as n,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何在 Bash 中编写函数 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Bash 中编写函数 | LCTT (202006) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Bash 中编写函数 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Bash 中编写函数 | LCTT (202006) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202006/20200610 How to write functions in Bash","title":"如何在 Bash 中编写函数","tag":"202006","desc":""},"relativePath":"202006/20200610 How to write functions in Bash.md","filePath":"[post].md"}'),u={name:"202006/20200610 How to write functions in Bash.md"};function h(g,s,b,f,k,m){const a=o("Link");return r(),d("div",null,[s[26]||(s[26]=t(`<h1 id="如何在-bash-中编写函数" tabindex="-1">如何在 Bash 中编写函数 <a class="header-anchor" href="#如何在-bash-中编写函数" aria-label="Permalink to “如何在 Bash 中编写函数”">​</a></h1><blockquote><p>通过编写函数来减少代码的冗余和维护。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202006/17/125913hf1efce5c48cebrc.jpg" alt=""></p><p>在编程时，实际上是在定义要由计算机执行的<ruby>过程<rt>procedure</rt></ruby>或<ruby>例程<rt>routine</rt></ruby>。一个简单的类比是将计算机编程与烤面包进行比较：你一次列出了要组建工作环境的配料，然后列出了烤面包所必须采取的步骤。在编程和烘烤中，必须以不同的间隔重复执行某些步骤。例如，在烤面包中，这可能是酵母培养的过程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>STIR=100</span></span>
<span class="line"><span>SNOOZE=86400</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function feed_culture {</span></span>
<span class="line"><span>  remove_from(pantry)</span></span>
<span class="line"><span>  add(flour, water)</span></span>
<span class="line"><span>  stir($STIR)</span></span>
<span class="line"><span>  sleep($SNOOZE)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>然后，揉面和醒发面团：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>KNEAD=600</span></span>
<span class="line"><span>SNOOZE=7200</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function process_dough {</span></span>
<span class="line"><span>  remove_from(proofing_drawer)</span></span>
<span class="line"><span>  knead($KNEAD)</span></span>
<span class="line"><span>  return_to_drawer($SNOOZE)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在编程中，这些<ruby>子例程<rt>subroutines</rt></ruby>可以表示为<ruby>函数<rt>function</rt></ruby>。函数对程序员很重要，因为它们有助于减少代码中的冗余，从而减少了所需的维护量。例如，在以编程方式烤制面包的假想场景中，如果你需要更改面团醒发的用时，只要你之前使用函数，那么你只需更改一次用时，或使用变量（在示例代码中为 <code>SNOOZE</code>）或直接在处理面团的子程序中更改用时。这样可以节省你很多时间，因为你不必通过你的代码库遍历每个可能正在醒发的面团，更不用说担心错过一个。许多 bug 是由未更改的缺失的值或执行不正确的 <code>sed</code> 命令引起的，它们希望捕获所有可能而不必手动寻找。</p>`,8)),p("p",null,[s[1]||(s[1]=n("在 ",-1)),e(a,{href:"https://opensource.com/resources/what-bash"},{default:i(()=>[...s[0]||(s[0]=[n("Bash",-1)])]),_:1}),s[2]||(s[2]=n(" 中，无论是在编写的脚本或在独立的文件中，定义函数和使用它们一样简单。如果将函数保存到独立的文件中。那么可以将它 ",-1)),s[3]||(s[3]=p("code",null,"source",-1)),s[4]||(s[4]=n(" 到脚本中，就像 ",-1)),s[5]||(s[5]=p("code",null,"include",-1)),s[6]||(s[6]=n(" C 语言或 C++ 中的库或将模块 ",-1)),s[7]||(s[7]=p("code",null,"import",-1)),s[8]||(s[8]=n(" 到 Python 中一样。要创建一个 Bash 函数，请使用关键字 ",-1)),s[9]||(s[9]=p("code",null,"function",-1)),s[10]||(s[10]=n("：",-1))]),s[27]||(s[27]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function foo {</span></span>
<span class="line"><span># code here</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这是一个如何在函数中使用参数的例子（有些人为设计，因此可能会更简单）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/env bash</span></span>
<span class="line"><span>ARG=$1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function mimic {</span></span>
<span class="line"><span>  if [[ -z $ARG ]]; then</span></span>
<span class="line"><span>    ARG=&#39;world&#39;</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>  echo &quot;hello $ARG&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mimic $ARG</span></span></code></pre></div><p>结果如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./mimic</span></span>
<span class="line"><span>hello world</span></span>
<span class="line"><span>$ ./mimic everybody</span></span>
<span class="line"><span>hello everybody</span></span></code></pre></div><p>请注意脚本的最后一行，它会执行该函数。对于编写脚本的新手来说，这是一个普遍的困惑点：函数不会自动执行。它们作为<em>潜在的</em>例程存在，直到被调用。</p><p>如果没有调用该函数，那么函数只是被定义，并且永远不会运行。</p><p>如果你刚接触 Bash，请尝试在包含最后一行的情况下执行示例脚本一次，然后在注释掉最后一行的情况下再次执行示例脚本。</p><h3 id="使用函数" tabindex="-1">使用函数 <a class="header-anchor" href="#使用函数" aria-label="Permalink to “使用函数”">​</a></h3><p>即使对于简单的脚本，函数也是很重要的编程概念。你越适应函数，在面对一个不仅需要声明性的命令行，还需要更多动态的复杂问题时，你就会越容易。将通用函数保存在单独的文件中还可以节省一些工作，因为它将帮助你建立常用的程序，以便你可以在项目间重用它们。看看你的脚本习惯，看是否适合使用函数。</p><hr>`,11)),p("p",null,[s[12]||(s[12]=n("via: ",-1)),e(a,{href:"https://opensource.com/article/20/6/bash-functions"},{default:i(()=>[...s[11]||(s[11]=[n("https://opensource.com/article/20/6/bash-functions",-1)])]),_:1})]),p("p",null,[s[17]||(s[17]=n("作者：",-1)),e(a,{href:"https://opensource.com/users/seth"},{default:i(()=>[...s[13]||(s[13]=[n("Seth Kenlon",-1)])]),_:1}),s[18]||(s[18]=n(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[14]||(s[14]=[n("lujun9972",-1)])]),_:1}),s[19]||(s[19]=n(" 译者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[15]||(s[15]=[n("geekpi",-1)])]),_:1}),s[20]||(s[20]=n(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[16]||(s[16]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[23]||(s[23]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[21]||(s[21]=[n("LCTT",-1)])]),_:1}),s[24]||(s[24]=n(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[22]||(s[22]=[n("Linux中国",-1)])]),_:1}),s[25]||(s[25]=n(" 荣誉推出",-1))])])}const C=l(u,[["render",h]]);export{T as __pageData,C as default};
